import{_ as s,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2018-09-06","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-09-06","date":"2018-09-06T00:00:00.000Z","updated":"2018-09-11T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","bufferless","小向量"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-09-06.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-09-06.md","lastUpdated":1780460162000}'),i={name:"posts/2018/Ceph_Performance_Meeting_2018-09-06.md"};function a(o,e,n,p,f,g){return l(),t("div",null,[...e[0]||(e[0]=[r("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2018年9月6日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Alex, auditing, TC 70, Casey, Madden, Sage, Greg, Anna, Neha, Radek, Mike, Jesse, Branislav 等</p><p><strong>会议主题</strong>： Ceph分布式存储系统性能优化，重点关注bufferless的使用和优化</p><p><strong>会议内容</strong>：</p><ul><li><strong>bufferless使用情况</strong>： <ul><li>bufferless在Ceph中被广泛使用，但存在一些问题，例如内存碎片化、迭代器失效、缓存行争用等。</li><li>一些团队成员对使用bufferless的必要性表示质疑，认为可能存在过度使用的情况。</li></ul></li><li><strong>优化方案讨论</strong>： <ul><li>探讨了使用small vector替换standard list的可能性，但测试结果并不一致，有时甚至出现性能下降。</li><li>讨论了使用bufferless的不同场景，例如编码/解码、IO操作等，并分析了不同场景对bufferless的需求。</li><li>讨论了使用bufferless时的迭代器失效和缓存行争用问题，并提出了可能的解决方案，例如使用不同的数据结构、优化工作流程等。</li><li>讨论了使用bufferless时的内存分配和释放问题，并提出了优化方案，例如预分配内存、减少不必要的内存分配等。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>由Braddock负责清理bufferless接口，整理出不必要的功能，并尝试使用small vector进行优化。</li><li>由Casey、Radek和key foo负责SeaStar方面的优化，尝试将SeaStar特定缓冲区的原子引用计数改为非原子引用计数。</li><li>由其他团队成员继续探索使用vector进行优化的可能性，并使用微基准测试分析其性能影响。</li><li>由Mike和Jesse讨论OMAP和PG日志等话题。</li></ul></li></ul><p><strong>关键信息</strong>：</p><ul><li>bufferless在Ceph中被广泛使用，但存在一些问题，需要进一步优化。</li><li>使用small vector替换standard list的优化方案需要进一步评估。</li><li>使用bufferless时需要考虑迭代器失效和缓存行争用问题。</li><li>使用bufferless时需要优化内存分配和释放。</li><li>需要进一步探索使用vector进行优化的可能性。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了多个英文关键词，如bufferless、small vector、standard list、SeaStar、OMAP、PG日志等，这些关键词与Ceph分布式存储系统的性能优化相关。</li></ul>",11)])])}const d=s(i,[["render",a]]);export{_ as __pageData,d as default};
